<?php $editing=!empty($service);$title=$editing?'Edit Service':'Add Service';require __DIR__.'/../layouts/header.php';$action=$editing?route('service.edit',['id'=>$service['id']]):route('services');?><div class="pagehead"><h1><?=$title?></h1></div><form class="panel form" method="post" action="<?=$action?>"><?=csrf_field()?><div class="form-grid"><label>Service name<input name="name" required value="<?=e($service['name']??'')?>"></label><label>Category<input name="category" value="<?=e($service['category']??'')?>"></label><label>Price<input name="price" type="number" step="0.01" value="<?=e($service['price']??'0')?>"></label><label>Approval level<select name="approval_level"><?php for($i=0;$i<=4;$i++):?><option value="<?=$i?>" <?=((int)($service['approval_level']??2)===$i?'selected':'')?>>Level <?=$i?></option><?php endfor;?></select></label><label class="wide">Description<textarea name="description" rows="5"><?=e($service['description']??'')?></textarea></label><label><input type="checkbox" name="automation_enabled" value="1" <?=isset($service)?(!empty($service['automation_enabled'])?'checked':''):'checked'?>> Automation enabled</label></div><button class="primary"><?=$editing?'Update Service':'Create Service'?></button></form><?php require __DIR__.'/../layouts/footer.php';?>
